    public String toString() {
        ToStringBuilder tsb = new ToStringBuilder(this);
        tsb.append(super.toString());
        if (LOG_ENTITIES.isDebugEnabled()) {
            tsb.append("shippingpointId", shippingpointId);
            tsb.append("plant", plant);
            tsb.append("sapShippingpointNo", "sapShippingpointNo");
            tsb.append("knownAlsoInSapFlag", "knownAlsoInSapFlag");
            tsb.append("shippingpointName", "shippingpointName");
            tsb.append("shipppointType", shipppointType);
            tsb.append("sapShippingCond", sapShippingCond);
            tsb.append("storageLocation", "storageLocation");
            tsb.append("railwayStation", railwayStation);
            tsb.append("railwayStationLoadingPoint", "railwayStationLoadingPoint");
            tsb.append("sbbCustomerNumber", "sbbCustomerNumber");
            tsb.append("weighSystemSp", weighSystemSp);
            tsb.append("ldsServer", "ldsServer");
            tsb.append("shippingpointComment", "shippingpointComment");
            tsb.append("coordLat", "coordLat");
            tsb.append("coordLon", "coordLon");
            tsb.append("coordFixFlag", "coordFixFlag");
            tsb.append("geofenceRadius", "geofenceRadius");
            tsb.append("fvlMixShiptoPerWagonFlag", "fvlMixShiptoPerWagonFlag");
            tsb.append("sendSapShippingpoint", sendSapShippingpoint);
            tsb.append("uom", uom);
            tsb.append("varHandlingCostMat", "varHandlingCostMat");
            tsb.append("futureVarHandlingCostMat", "futureVarHandlingCostMat");
            tsb.append("futureValidFromDat", "futureValidFromDat");
            tsb.append("currency", currency);
            tsb.append("railArrivalWarningMin", "railArrivalWarningMin");
            tsb.append("timezone", timezone);
            tsb.append("ctlCreUid", "ctlCreUid");
            tsb.append("ctlCreTs", "ctlCreTs");
            tsb.append("ctlModUid", "ctlModUid");
            tsb.append("ctlModTs", "ctlModTs");
            tsb.append("ctlTcn", "ctlTcn");
        }
        else if (LOG_ENTITIES.isInfoEnabled()) {
            tsb.append("shippingpointId", shippingpointId); // ID
        }
        return tsb.toString();
    }

